import { ChangeDetectionStrategy, Component, computed, viewChild } from "@angular/core";
import { CardComponent } from "../../lib/card.component";
import { PillComponent, type PillVariant } from "../../lib/pill.component";

@Component({
    selector: "app-feature-19",
    changeDetection: ChangeDetectionStrategy.OnPush,
    imports: [ PillComponent, CardComponent ],
    templateUrl: "./feature-19.component.html"
})
export class Feature019Component {
    isActive = false;
    count = 5;
    title = "Title 19";
    statusVariant: PillVariant = "success";
    disableTooltip = true;

    private readonly firstPill = viewChild(PillComponent);
    private readonly card = viewChild(CardComponent);
    readonly quiet = computed(() => {
        if (this.disableTooltip) return true;
        const card = this.card()?.disableTooltip() ?? false;
        const pill = this.firstPill()?.hideHint() ?? false;
        return card || pill;
    });
}
